  // 3. availability check: only icons in ICON_DATA get CSS rules; missing fall back to native
  function scanAvailableIcons() {
    const allFiles = new Set();
    const available = new Set();

    for (const group of Object.values(ICON_REGISTRY)) {
      for (const entry of group) {
        if (entry.file) {
          allFiles.add(entry.file);
          if (ICON_DATA[entry.file]) available.add(entry.file);
        }
      }
    }

    console.log(LOG_PREFIX, `Found ${available.size}/${allFiles.size} embedded icons`);
    if (available.size > 0) {
      console.log(LOG_PREFIX, "Available:", [...available].join(", "));
    }
    return available;
  }


  // 4. CSS gen: A=selector-based, B=path-fingerprint via :has() (zero-flicker, browser paint)
  // technique: mask-image w/ data URI + currentColor fill + contain sizing
  // 4A. selector-based mask rule
  function generateIconCSS(entry) {
    const dataUri = iconUrl(entry.file);
    if (!dataUri) return "";
    const url = `url("${dataUri}")`;
    const selectorStr = entry.selectors.join(",\n      ");

    // hide original SVG children (transparent fill/stroke)
    const hideSelectors = entry.selectors
      .map(s => `${s} path, ${s} circle, ${s} line, ${s} rect`)
      .join(",\n      ");

    return `
      /* ${entry.id} */
      ${selectorStr} {
        -webkit-mask-image: ${url};
        mask-image: ${url};
        -webkit-mask-size: contain;
        mask-size: contain;
        -webkit-mask-repeat: no-repeat;
        mask-repeat: no-repeat;
        -webkit-mask-position: center;
        mask-position: center;
        background: currentColor !important;
      }
      ${hideSelectors} {
        fill: transparent !important;
        stroke: transparent !important;
      }`;
  }

  // 4B. fingerprint-based: svg:has(path[d^="..."]) chained on |
  function generateFingerprintCSS(entry) {
    const dataUri = iconUrl(entry.file);
    if (!dataUri) return "";
    const url = `url("${dataUri}")`;

    const fpParts = entry.pathFingerprint.split("|");
    const hasChain = fpParts.map(fp => `:has(path[d^="${fp}"])`).join("");
    const sel = `svg${hasChain}`;

    return `
      /* ${entry.id} ← fingerprint */
      ${sel} {
        -webkit-mask-image: ${url} !important;
        mask-image: ${url} !important;
        -webkit-mask-size: contain !important;
        mask-size: contain !important;
        -webkit-mask-repeat: no-repeat !important;
        mask-repeat: no-repeat !important;
        -webkit-mask-position: center !important;
        mask-position: center !important;
        background: currentColor !important;
      }
      ${sel} > * {
        fill: transparent !important;
        stroke: transparent !important;
      }`;
  }

  /** Build and inject the full CSS stylesheet */
  function injectCSS(availableFiles) {
    // Remove existing style if present
    const existing = document.getElementById(STYLE_ID);
    if (existing) existing.remove();

    const rules = [];
    rules.push(`/* Vantagraph Custom Icons - auto-generated */`);

    // A. selector-based rules
    for (const [groupName, entries] of Object.entries(ICON_REGISTRY)) {
      if (groupName === "contextMenu") continue;

      const groupRules = [];
      for (const entry of entries) {
        if (!entry.selectors || entry.selectors.length === 0) continue;
        if (!availableFiles.has(entry.file)) continue;
        groupRules.push(generateIconCSS(entry));
      }

      if (groupRules.length > 0) {
        rules.push(`\n      /* ${groupName} */`);
        rules.push(...groupRules);
      }
    }

    // B. fingerprint rules: sorted ASC so longer/specific win cascade
    const fpEntries = [];
    for (const entries of Object.values(ICON_REGISTRY)) {
      for (const entry of entries) {
        if (!entry.pathFingerprint) continue;
        if (!availableFiles.has(entry.file)) continue;
        fpEntries.push(entry);
      }
    }
    fpEntries.sort((a, b) => a.pathFingerprint.length - b.pathFingerprint.length);

    if (fpEntries.length > 0) {
      rules.push(`\n      /* fingerprint rules: svg:has(path[d^=...]) */`);
      for (const entry of fpEntries) {
        rules.push(generateFingerprintCSS(entry));
      }
    }

    const styleEl = document.createElement("style");
    styleEl.id = STYLE_ID;
    styleEl.textContent = rules.join("\n");
    document.head.appendChild(styleEl);

    console.log(LOG_PREFIX, `CSS injected: ${availableFiles.size} icons (${fpEntries.length} fingerprint rules)`);
  }


